SELECT
    CONCAT(sku.sku_no,'[', sku.name_cn, ']') AS name,
    COALESCE(SUM(doit.amount_after), 0) AS sales,
    COALESCE(SUM(droi.order_fee) + SUM(dri.refund_amount), 0)as amount
FROM dmp_sku_info sku
LEFT JOIN dmp_order_item doit ON sku.sku_no = doit.sku_no
LEFT JOIN dmp_order_info doi ON doi.id = doit.order_id
LEFT JOIN dmp_return_order_info droi ON droi.platform_order_id = doi.platform_order_id
LEFT JOIN dmp_refund_info dri ON dri.platform_order_id = doi.platform_order_id
LEFT JOIN dmp_shop_info dsi ON dsi.platform_shop_no = doi.shop_no
where  ( (doit.sell_price > 0 and doit.quantity > 0) OR dri.refund_amount > 0 OR droi.order_fee > 0 )


            AND doi.platform_create_time >= #{params.startTime}


            AND doi.platform_create_time <= #{params.endTime}




            AND doi.delivery_time >= #{params.startTime}


            AND doi.delivery_time <= #{params.endTime}





        AND doi.dept_id IN

            #{deptId}




        AND doi.source_platform IN

            #{platform}




        AND doi.site IN

            #{site}





        AND doi.shop_no IN

            #{shopNo}





        AND sku.sku_no IN

            #{sku}




        AND sku.parent_category_name IN

            #{category}




        AND sku.brand_name IN

            #{brand}





        AND doi.charge_id IN

            #{userId}




        #{params.permissionSql}

GROUP BY sku.sku_no,sku.name_cn

