SELECT
AS name, SUM(droi.order_fee) AS amount,
COALESCE(SUM(droi.order_fee * COALESCE(droi.currency_rate, 0)), 0)
COALESCE(SUM(droi.order_fee), 0)
COALESCE(SUM(droi.order_fee * COALESCE(droi.cny_settle_rate, 0)), 0)
AS amount FROM dmp_order_info AS doi LEFT JOIN dmp_return_order_info droi ON droi.platform_order_id = doi.platform_order_id left join dmp_order_item AS doit on doi.id = doit.order_id left join product_detail AS pd on doit.sku_no = pd.sku_no left join product_info AS pi on pi.id = pd.product_id
AND to_char(doi.platform_create_time, 'YYYY-MM-dd HH:mm:ss') >= #{startTime}
AND to_char(doi.platform_create_time, 'YYYY-MM-dd HH:mm:ss') <= #{endTime}
AND doit.sku_no = #{sku}
GROUP BY ORDER BY name

